<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>Program Management — MCQ Bank</title>
<style>
:root{--navy:#12345a;--blue:#1769aa;--ink:#18324f;--muted:#647995;--line:#dbe5f1;--surface:#f2f6fc;--white:#fff}
*{box-sizing:border-box}body{margin:0;padding:24px 18px;font-family:Inter,"Segoe UI",Arial,sans-serif;background:linear-gradient(180deg,#eaf2fc 0,#f5f8fd 260px,#f4f7fb 100%);color:var(--ink);font-size:14px}main{max-width:1180px;margin:0 auto}
.top{display:flex;justify-content:space-between;align-items:center;gap:18px;padding:23px 26px;margin-bottom:20px;border-radius:16px;background:linear-gradient(120deg,#102b4b,#174b7e 60%,#1769aa);color:#fff;box-shadow:0 12px 28px #12345a20}.eyebrow{font-size:11px;letter-spacing:1.3px;font-weight:800;color:#a9d3ff;margin-bottom:7px}.top h1{font-size:clamp(23px,3vw,30px);margin:0 0 7px;color:#fff}.top p{margin:0;color:#d8e8fb;font-size:13px}.top a{padding:10px 14px;border-radius:9px;background:#fff;color:#174f88;text-decoration:none;font-weight:750;white-space:nowrap}
.panel{background:#fff;border:1px solid var(--line);border-radius:14px;padding:22px;margin-bottom:18px;box-shadow:0 6px 20px #1a3a5f08}.panel h2{margin:0 0 18px;color:var(--navy);font-size:18px}.panel h2:before{content:"";display:inline-block;width:4px;height:20px;border-radius:5px;background:#2878c8;margin-right:10px;vertical-align:-4px}
label{display:block;font-size:13px;font-weight:700;color:#274665;margin:0 0 6px}input,button{font:inherit;border-radius:9px;font-size:14px}input{display:block;width:100%;padding:11px 12px;border:1px solid #cbd9e9;min-height:42px;color:#1d3552}input:focus{outline:none;border-color:#3987d5;box-shadow:0 0 0 3px #3987d522}button{border:0;cursor:pointer;font-weight:700;padding:10px 15px;min-height:38px;background:linear-gradient(135deg,#1769aa,#2479c7);color:#fff}button:hover{filter:brightness(.96)}.secondary{background:#647995}.warning{background:#fff0d9;color:#895300}.success-btn{background:#e5f7ed;color:#176534;border:1px solid #bde8ca}.msg{padding:12px 14px;border-radius:9px;margin:0 0 15px;font-weight:600}.ok{background:#eaf8ef;color:#176534;border:1px solid #bde8ca}.err{background:#fff0f0;color:#9b1c1c;border:1px solid #f5c4c4}.muted{color:var(--muted);font-size:12px}.form-grid{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;align-items:end}.form-grid input{margin:0}.form-actions{display:flex;gap:8px;flex-wrap:wrap}.toolbar{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:13px;flex-wrap:wrap}.toolbar input{max-width:360px}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:separate;border-spacing:0;font-size:13px}th,td{text-align:left;padding:12px 13px;border-bottom:1px solid #e8eef6;vertical-align:middle}th{background:#edf4fc;color:#234d78;font-size:12px;text-transform:uppercase;letter-spacing:.4px}tbody tr:nth-child(even){background:#fbfdff}tbody tr:hover{background:#f1f7ff}tbody tr:last-child td{border-bottom:0}.status{display:inline-block;border-radius:20px;padding:5px 9px;font-size:11px;font-weight:800}.active{background:#e5f7ed;color:#176534}.inactive{background:#fff0f0;color:#9b1c1c}.actions{display:flex;gap:7px;flex-wrap:wrap}.actions form{margin:0}.actions button{padding:7px 10px;min-height:32px;font-size:12px}.empty{text-align:center;color:var(--muted);padding:26px}@media(max-width:650px){body{padding:12px}.top{align-items:flex-start;flex-direction:column;padding:20px}.panel{padding:16px}.form-grid{grid-template-columns:1fr}.form-actions button{width:100%}th,td{padding:10px;font-size:12px}}
</style>
</head>
<body><main>
<header class="top"><div><div class="eyebrow">RIPHAH INTERNATIONAL UNIVERSITY · PESHAWAR CAMPUS</div><h1>Program Management</h1><p>Manage academic programs and their active status.</p></div><a href="<?= site_url('dashboard/admin') ?>">← Dashboard</a></header>
<?php if (! empty($success)): ?><div class="msg ok"><?= esc($success) ?></div><?php endif; ?>
<?php if (! empty($error)): ?><div class="msg err"><?= esc($error) ?></div><?php endif; ?>
<section class="panel"><h2 id="form-title">Add Academic Program</h2><form method="post" action="<?= site_url('master/programs') ?>" id="program-form"><?= csrf_field() ?><input type="hidden" name="action" value="save"><input type="hidden" name="progId" id="progId" value=""><div class="form-grid"><div><label for="progName">Program Name</label><input id="progName" name="progName" type="text" maxlength="150" placeholder="e.g. MBBS, BDS, BS Nursing" autocomplete="off" required><div class="muted" style="margin-top:7px">Program names must be unique. Existing program IDs are preserved.</div></div><div class="form-actions"><button type="submit" id="save-button">Save Program</button><button type="button" class="secondary" id="cancel-button" hidden>Cancel Edit</button></div></div></form></section>
<section class="panel"><div class="toolbar"><h2 style="margin:0">Existing Programs (<span id="visible-count"><?= count($records) ?></span> / <?= count($records) ?>)</h2><input id="search" type="search" placeholder="Search by program name or ID…" aria-label="Search programs"></div><div class="muted" style="margin:-3px 0 13px">Use Edit to change a program name. Deactivate rather than delete programs to preserve linked records and mappings.</div><div class="table-wrap"><table><thead><tr><th style="width:100px">Program ID</th><th>Program Name</th><th style="width:130px">Status</th><th style="width:200px">Actions</th></tr></thead><tbody id="program-rows">
<?php if (empty($records)): ?><tr><td colspan="4" class="empty">No programs found.</td></tr><?php else: foreach ($records as $row): ?><tr class="program-row" data-id="<?= esc((string)$row['progId']) ?>" data-name="<?= esc((string)$row['progName']) ?>"><td><?= esc((string)$row['progId']) ?></td><td class="program-name"><?= esc($row['progName']) ?></td><td><span class="status <?= (int)$row['is_Active'] === 1 ? 'active' : 'inactive' ?>"><?= (int)$row['is_Active'] === 1 ? 'Active' : 'Inactive' ?></span></td><td><div class="actions"><button type="button" class="edit-button" data-id="<?= esc((string)$row['progId']) ?>" data-name="<?= esc($row['progName']) ?>">Edit</button><form method="post" action="<?= site_url('master/programs') ?>"><?= csrf_field() ?><input type="hidden" name="action" value="toggle"><input type="hidden" name="progId" value="<?= esc((string)$row['progId']) ?>"><button type="submit" class="<?= (int)$row['is_Active'] === 1 ? 'warning' : 'success-btn' ?>"><?= (int)$row['is_Active'] === 1 ? 'Deactivate' : 'Activate' ?></button></form></div></td></tr><?php endforeach; endif; ?></tbody></table></div></section>
</main><script>
(() => {const form=document.getElementById('program-form'),id=document.getElementById('progId'),name=document.getElementById('progName'),title=document.getElementById('form-title'),save=document.getElementById('save-button'),cancel=document.getElementById('cancel-button'),search=document.getElementById('search'),rows=[...document.querySelectorAll('.program-row')],count=document.getElementById('visible-count');
function resetForm(){id.value='';name.value='';title.textContent='Add Academic Program';save.textContent='Save Program';cancel.hidden=true;}
document.querySelectorAll('.edit-button').forEach(btn=>btn.addEventListener('click',()=>{id.value=btn.dataset.id;name.value=btn.dataset.name;title.textContent='Edit Academic Program (ID '+btn.dataset.id+')';save.textContent='Update Program';cancel.hidden=false;name.focus();form.scrollIntoView({behavior:'smooth',block:'start'});}));cancel.addEventListener('click',resetForm);
search.addEventListener('input',()=>{const q=search.value.trim().toLocaleLowerCase();let n=0;rows.forEach(row=>{const show=(row.dataset.id+' '+row.dataset.name).toLocaleLowerCase().includes(q);row.hidden=!show;if(show)n++;});count.textContent=n;});
document.querySelectorAll('form').forEach(f=>{if(f.querySelector('input[name="action"]')?.value==='toggle'){f.addEventListener('submit',e=>{const button=f.querySelector('button');const action=button.textContent.trim().toLowerCase();if(!confirm('Are you sure you want to '+action+' this program? Existing records and mappings will be preserved.'))e.preventDefault();});}});
})();
</script></body></html>
